function getATH(ticker) {
  var apiKey = "TUA_API_KEY";
  var url = "https://api.cryptorank.io/v1/crypton/assets/" + ticker + "/ath?api_key=" + apiKey;
  var response = UrlFetchApp.fetch(url);
  var data = JSON.parse(response.getContentText());

  if (data.status !== "success") {
    Logger.log("Errore nella richiesta dell'ATH per il ticker: " + ticker);
    return "Errore";
  }

  // Elementi della riga
  var nome = data.name;
  var prezzoATH = data.price_ath.toString();
  var dataATH = data.date_ath;
  var percentualeDaATH = data.percent_from_ath.toString();
  var percentualeAATH = data.percent_to_ath.toString();

  // Restituisce i dati come array
  return [nome, prezzoATH, dataATH, percentualeDaATH, percentualeAATH];
}

function getTickers() {
  var apiKey = "TUA_API_KEY";
  var url = "https://api.cryptorank.io/v1/crypton/currencies?size=100&api_key=" + apiKey; // Modifica la dimensione dell'elenco in base alle tue esigenze
  var response = UrlFetchApp.fetch(url);
  var data = JSON.parse(response.getContentText());

  if (data.status !== "success") {
    Logger.log("Errore nel recupero dell'elenco dei ticker");
    return [];
  }

  var tickers = [];
  for (var i = 0; i < data.data.length; i++) {
    tickers.push(data.data[i].ticker);
  }
  return tickers;
}
