  var prezzoATH = data[0].ath.toString();
  var dataATH = data[0].ath_date;
  var percentualeDaATH = data[0].ath_change_percentage.toString();

  // Calcola la percentuale per raggiungere l'ATH
  var percentualeAATH = (100 / (100 + parseFloat(percentualeDaATH))).toString();

  // Restituisce i dati come array
  return [nome, prezzoATH, dataATH, percentualeDaATH, percentualeAATH];
}
